import React, { useEffect, useState } from "react";
import API from "../api"; // axios instance

export default function TeacherDashboard({ user, logout }) {
  const [students, setStudents] = useState([]);
  const [attendance, setAttendance] = useState({});
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [loading, setLoading] = useState(false);

  // Assignment form state
  const [assignment, setAssignment] = useState({
    title: "",
    content: "",
    file: null,
    dueDate: "",
  });

  // Assignment list state
  const [assignmentList, setAssignmentList] = useState([]);

  // Fetch students
  useEffect(() => {
    async function fetchStudents() {
      try {
        const res = await API.get("/users/students");
        setStudents(res.data);
      } catch (err) {
        alert("Failed to load students");
      }
    }
    fetchStudents();
  }, []);

  // Fetch assignments on mount
  useEffect(() => {
    async function fetchAssignments() {
      try {
        const res = await API.get("/assignments");
        setAssignmentList(res.data);
      } catch (err) {
        alert("Failed to load assignments");
      }
    }
    fetchAssignments();
  }, []);

  // Toggle attendance for a student
  const toggleAttendance = (studentId) => {
    setAttendance((prev) => ({
      ...prev,
      [studentId]: !prev[studentId],
    }));
  };

  // Save attendance to backend
  const saveAttendance = async () => {
    setLoading(true);
    try {
      const attendanceList = students.map((stu) => ({
        studentId: stu._id,
        present: attendance[stu._id] || false,
      }));
      await API.post("/attendance", { attendanceList, date });
      alert("Attendance saved!");
    } catch (err) {
      alert("Failed to save attendance");
    } finally {
      setLoading(false);
    }
  };

  // Handle assignment input changes
  const handleAssignmentChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "file") {
      setAssignment({ ...assignment, file: files[0] });
    } else {
      setAssignment({ ...assignment, [name]: value });
    }
  };

  // Submit new assignment
  const handleAssignmentSubmit = async (e) => {
    e.preventDefault();

    if (!assignment.title || !assignment.file || !assignment.dueDate) {
      return alert("Please provide title, file, and due date.");
    }

    const formData = new FormData();
    formData.append("title", assignment.title);
    formData.append("content", assignment.content);
    formData.append("dueDate", assignment.dueDate);
    formData.append("file", assignment.file);

    try {
      const res = await API.post("/assignments", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      alert("Assignment uploaded successfully");
      // Reset form
      setAssignment({ title: "", content: "", file: null, dueDate: "" });

      // Update assignment list with newly added assignment
      setAssignmentList((prev) => [res.data, ...prev]);
    } catch (err) {
      alert("Failed to upload assignment");
    }
  };

  return (
    <div style={{ padding: 20, maxWidth: 900, margin: "auto" }}>
      <h1>Teacher Dashboard</h1>
      <p>
        Welcome, {user.username} (Role: {user.role})
      </p>
      <button onClick={logout} style={{ marginBottom: 20 }}>
        Logout
      </button>

      {/* Attendance Section */}
      <h2>Mark Attendance</h2>
      <label>
        Select Date:{" "}
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          style={{ marginBottom: 20 }}
        />
      </label>

      <table
        border="1"
        cellPadding="8"
        style={{ width: "100%", borderCollapse: "collapse" }}
      >
        <thead>
          <tr>
            <th>Student Name</th>
            <th>Present</th>
          </tr>
        </thead>
        <tbody>
          {students.map((stu) => (
            <tr key={stu._id}>
              <td>{stu.username}</td>
              <td style={{ textAlign: "center" }}>
                <input
                  type="checkbox"
                  checked={!!attendance[stu._id]}
                  onChange={() => toggleAttendance(stu._id)}
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <button
        onClick={saveAttendance}
        disabled={loading}
        style={{ marginTop: 20, padding: 10 }}
      >
        {loading ? "Saving..." : "Save Attendance"}
      </button>

      {/* Assignment Upload Section */}
      <hr style={{ margin: "40px 0" }} />
      <h2>Upload Assignment</h2>
      <form
        onSubmit={handleAssignmentSubmit}
        style={{ display: "flex", flexDirection: "column", gap: 10 }}
      >
        <input
          type="text"
          name="title"
          placeholder="Assignment Title"
          value={assignment.title}
          onChange={handleAssignmentChange}
          required
        />
        <textarea
          name="content"
          placeholder="Optional Description"
          value={assignment.content}
          onChange={handleAssignmentChange}
          rows={4}
        />
        <label>
          Due Date:
          <input
            type="date"
            name="dueDate"
            value={assignment.dueDate}
            onChange={handleAssignmentChange}
            required
          />
        </label>
        <input
          type="file"
          name="file"
          onChange={handleAssignmentChange}
          accept=".pdf,.doc,.docx"
          required
        />
        <button type="submit">Upload Assignment</button>
      </form>

      {/* Submitted Assignments List */}
      <hr style={{ margin: "40px 0" }} />
      <h3>Submitted Assignments</h3>
      {assignmentList.length === 0 ? (
        <p>No assignments submitted yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          {assignmentList.map((a) => (
            <div
              key={a._id}
              style={{
                border: "1px solid #ccc",
                borderRadius: 8,
                padding: 20,
                backgroundColor: "#f9f9f9",
                boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
                maxWidth: 600,
                margin: "auto",
              }}
            >
              <div style={{ marginBottom: 10 }}>
                <strong>Title:</strong> {a.title}
              </div>
              <div style={{ marginBottom: 10 }}>
                <strong>Description:</strong> {a.content || "—"}
              </div>
              <div style={{ marginBottom: 10 }}>
                <strong>Due Date:</strong> {new Date(a.dueDate).toLocaleDateString()}
              </div>
              <div style={{ marginBottom: 10 }}>
                <strong>Submitted On:</strong> {new Date(a.createdAt).toLocaleDateString()}
              </div>
              <div>
                <strong>File:</strong>{" "}
                <a
                  href={`http://localhost:5000/${a.file}`}
                  target="_blank"
                  rel="noreferrer"
                  style={{ color: "#007bff", textDecoration: "underline" }}
                >
                  Download
                </a>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
